#include "nlsql.h"
#include <stdio.h>
int main(void){nlsql_context*c=NULL;nlsql_schema_builder*b=NULL;nlsql_schema*s=NULL;nlsql_policy*p=NULL;nlsql_compile_result*r=NULL;nlsql_config cfg={0};nlsql_compile_request q={0};const char*ir="(nlsql 1 (query (from orders o) (select (field (column o status) status))))";if(nlsql_context_create(&cfg,&c)!=NLSQL_OK||nlsql_schema_builder_create(c,&b)!=NLSQL_OK)return 1;if(nlsql_schema_builder_add_table(b,"public","orders",NLSQL_TABLE_TENANT_SCOPED)!=NLSQL_OK||nlsql_schema_builder_add_column(b,"public","orders","status",NLSQL_TYPE_TEXT,0)!=NLSQL_OK||nlsql_schema_builder_add_column(b,"public","orders","tenant_id",NLSQL_TYPE_UUID,NLSQL_COLUMN_TENANT_KEY)!=NLSQL_OK)return 1;if(nlsql_schema_builder_finalize(b,&s)!=NLSQL_OK||nlsql_policy_create(c,&p)!=NLSQL_OK||nlsql_policy_require_tenant(p,"public","orders","tenant_id")!=NLSQL_OK)return 1;q.ir=ir;q.schema=s;q.policy=p;q.dialect=NLSQL_DIALECT_POSTGRES;if(nlsql_compile_ir(c,&q,&r)!=NLSQL_OK)return 1;puts(nlsql_result_sql(r).sql);nlsql_compile_result_destroy(r);nlsql_policy_destroy(p);nlsql_schema_destroy(s);nlsql_schema_builder_destroy(b);nlsql_context_destroy(c);return 0;}
